-- Generated by dbml CLI

CREATE TABLE users (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    email TEXT,
    display_name TEXT,
    created_at TIMESTAMPTZ DEFAULT now()
);

CREATE TABLE projects (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    owner_id UUID,
    name TEXT,
    description TEXT,
    visibility PROJECT_VISIBILITY DEFAULT private,
    created_at TIMESTAMPTZ DEFAULT now(),
    updated_at TIMESTAMPTZ DEFAULT now(),
    archived_at TIMESTAMPTZ,
    (owner_id, CREATED_AT),
    (visibility, CREATED_AT)
);

CREATE TABLE project_members (
    project_id UUID,
    user_id UUID,
    role PROJECT_ROLE,
    created_at TIMESTAMPTZ DEFAULT now(),
    (project_id, USER_ID) UNIQUE
);

CREATE TABLE datasets (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    project_id UUID,
    name TEXT,
    source_type DATASET_SOURCE_TYPE,
    created_at TIMESTAMPTZ DEFAULT now(),
    updated_at TIMESTAMPTZ DEFAULT now(),
    archived_at TIMESTAMPTZ,
    (project_id, CREATED_AT),
    (project_id, ID) UNIQUE
);

CREATE TABLE dataset_versions (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    dataset_id UUID,
    version TEXT,
    manifest JSONB DEFAULT {}'::jsonb,
    status TEXT DEFAULT 'created',
    created_at TIMESTAMPTZ DEFAULT now(),
    (dataset_id, VERSION) UNIQUE,
    (dataset_id, CREATED_AT),
    (dataset_id, ID) UNIQUE
);

CREATE TABLE file_assets (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    dataset_version_id UUID,
    object_key TEXT,
    checksum TEXT,
    size_bytes BIGINT,
    media_type TEXT,
    created_at TIMESTAMPTZ DEFAULT now()
);

CREATE TABLE upload_sessions (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    dataset_id UUID,
    project_id UUID,
    status UPLOAD_SESSION_STATUS DEFAULT pending,
    expected_size_bytes BIGINT,
    checksum_sha256 TEXT,
    expires_at TIMESTAMPTZ,
    created_at TIMESTAMPTZ DEFAULT now(),
    (dataset_id, CREATED_AT),
    (status, EXPIRES_AT)
);

CREATE TABLE pipelines (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    project_id UUID,
    name TEXT,
    created_at TIMESTAMPTZ DEFAULT now(),
    updated_at TIMESTAMPTZ DEFAULT now(),
    (project_id, CREATED_AT),
    (project_id, ID) UNIQUE
);

CREATE TABLE pipeline_versions (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    pipeline_id UUID,
    version TEXT,
    definition JSONB,
    image_digest TEXT,
    created_at TIMESTAMPTZ DEFAULT now(),
    (pipeline_id, VERSION) UNIQUE
);

CREATE TABLE experiment_runs (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    pipeline_version_id UUID,
    dataset_version_id UUID,
    status RUN_STATUS DEFAULT queued,
    parameters JSONB DEFAULT {}'::jsonb,
    error TEXT,
    started_at TIMESTAMPTZ,
    finished_at TIMESTAMPTZ,
    created_at TIMESTAMPTZ DEFAULT now(),
    (status, CREATED_AT),
    (dataset_version_id, CREATED_AT),
    (pipeline_version_id, CREATED_AT)
);

CREATE TABLE artifacts (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    run_id UUID,
    object_key TEXT,
    checksum TEXT,
    media_type TEXT,
    metadata JSONB DEFAULT {}'::jsonb,
    created_at TIMESTAMPTZ DEFAULT now()
);

CREATE TABLE annotations (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    project_id UUID,
    dataset_version_id UUID,
    coordinate_space TEXT,
    coordinates JSONB,
    body TEXT,
    created_at TIMESTAMPTZ DEFAULT now(),
    (dataset_version_id, CREATED_AT),
    (project_id, CREATED_AT)
);

CREATE TABLE usage_records (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    user_id UUID,
    run_id UUID,
    resource_type TEXT,
    quantity BIGINT,
    created_at TIMESTAMPTZ DEFAULT now(),
    (user_id, CREATED_AT)
);

CREATE TABLE audit_events (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    actor_id UUID,
    action TEXT,
    resource_type TEXT,
    resource_id UUID,
    created_at TIMESTAMPTZ DEFAULT now(),
    (resource_type, RESOURCE_ID,,
    (actor_id, CREATED_AT)
);

CREATE TABLE outbox_events (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    event_type TEXT,
    payload JSONB,
    status OUTBOX_STATUS DEFAULT pending,
    created_at TIMESTAMPTZ DEFAULT now(),
    dispatched_at TIMESTAMPTZ,
    (status, CREATED_AT),
    (event_type, CREATED_AT)
);

CREATE TABLE idempotency_keys (
    key TEXT PRIMARY KEY,
    user_id UUID,
    request_hash TEXT,
    response JSONB,
    created_at TIMESTAMPTZ DEFAULT now(),
    (user_id, KEY) UNIQUE
);

